$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
if (-not (Test-Path '.\apps\api\src\app.module.ts')) { throw 'Run this script from C:\Users\HomePC\lumorius.' }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backupDir = Join-Path $root ".integration-backups\connectors-v2-$stamp"
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
$encoding = [System.Text.UTF8Encoding]::new($false)

function Read-Normalized([string]$Path) {
  [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path).Path).Replace("`r`n", "`n")
}
function Write-Utf8([string]$Path, [string]$Content) {
  $full = [System.IO.Path]::GetFullPath($Path)
  $dir = Split-Path -Parent $full
  if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [System.IO.File]::WriteAllText($full, $Content.Replace("`r`n", "`n").Replace("`n", "`r`n"), $encoding)
}
function Backup-IfExists([string]$Path) {
  if (Test-Path -LiteralPath $Path) {
    $dest = Join-Path $backupDir ($Path -replace '[\\/:*?"<>|]', '_')
    Copy-Item -LiteralPath $Path -Destination $dest -Force
  }
}
function Append-MissingEnv([string]$Path, [string]$Block) {
  if (-not (Test-Path -LiteralPath $Path)) { return }
  $content = Read-Normalized $Path
  $changed = $false
  foreach ($line in ($Block -split "`n")) {
    if ($line -match '^([A-Z0-9_]+)=') {
      $name = $Matches[1]
      if ($content -notmatch "(?m)^$([regex]::Escape($name))=") {
        $content += "`n$line`n"
        $changed = $true
      }
    }
  }
  if ($changed) { Write-Utf8 $Path $content }
}

