$pageContent = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($pageContentBase64))

$controller = @'
import {
  Body, Controller, Delete, Get, Param, Post, Query, Res, UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import type { Response } from 'express';
import { IntegrationsService } from './integrations.service';
import { CurrentUser, JwtPayload } from '../common/decorators/current-user.decorator';

@ApiTags('integrations')
@ApiBearerAuth()
@UseGuards(AuthGuard('jwt'))
@Controller('integrations')
export class IntegrationsController {
  constructor(private readonly integrationsService: IntegrationsService) {}

  @Get()
  @ApiOperation({ summary: 'List integration catalog and verified organisation connection states' })
  list(@CurrentUser() user: JwtPayload) {
    return this.integrationsService.listForUser(user);
  }

  @Post(':provider/connect')
  @ApiOperation({ summary: 'Start OAuth for a supported provider' })
  connect(@CurrentUser() user: JwtPayload, @Param('provider') provider: string) {
    return this.integrationsService.beginConnect(user, provider);
  }

  @Post(':provider/configure')
  @ApiOperation({ summary: 'Configure an API-key or webhook integration' })
  configure(
    @CurrentUser() user: JwtPayload,
    @Param('provider') provider: string,
    @Body() body: { apiKey?: string; appKey?: string; webhookUrl?: string },
  ) {
    return this.integrationsService.configureConnector(user, provider, body);
  }

  @Post(':provider/sync')
  @ApiOperation({ summary: 'Import recent provider content into Company Brain' })
  sync(@CurrentUser() user: JwtPayload, @Param('provider') provider: string) {
    return this.integrationsService.syncForUser(user, provider);
  }

  @Delete(':provider')
  @ApiOperation({ summary: 'Disconnect a provider from the current organisation' })
  disconnect(@CurrentUser() user: JwtPayload, @Param('provider') provider: string) {
    return this.integrationsService.disconnect(user, provider);
  }
}

// OAuth callbacks use one-time, short-lived state stored by the server, not a session cookie.
@ApiTags('integration-oauth')
@Controller('integrations')
export class IntegrationsOAuthController {
  constructor(private readonly integrationsService: IntegrationsService) {}

  @Get(':provider/callback')
  @ApiOperation({ summary: 'Complete OAuth and return to the integrations page' })
  async callback(
    @Param('provider') provider: string,
    @Query('code') code: string | undefined,
    @Query('state') state: string | undefined,
    @Query('error') providerError: string | undefined,
    @Res() response: Response,
  ) {
    try {
      const url = await this.integrationsService.completeOAuth(provider, code, state, providerError);
      return response.redirect(302, url);
    } catch {
      return response.redirect(302, this.integrationsService.resultRedirect(provider, 'error'));
    }
  }
}
'@
$module = @'
import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { DatabaseModule } from '../database/database.module';
import { DocumentsModule } from '../documents/documents.module';
import { IntegrationsController, IntegrationsOAuthController } from './integrations.controller';
import { IntegrationsService } from './integrations.service';

@Module({
  imports: [ConfigModule, DatabaseModule, DocumentsModule],
  controllers: [IntegrationsController, IntegrationsOAuthController],
  providers: [IntegrationsService],
  exports: [IntegrationsService],
})
export class IntegrationsModule {}
'@
$migration = @'
-- Lumorius integrations: encrypted organisation connections, OAuth state and imported-source idempotency.
CREATE TABLE IF NOT EXISTS integration_connections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  provider text NOT NULL,
  status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'error')),
  account_email text,
  encrypted_credentials text NOT NULL,
  scopes text[] NOT NULL DEFAULT ARRAY[]::text[],
  connected_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  last_synced_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT NOW(),
  updated_at timestamptz NOT NULL DEFAULT NOW(),
  CONSTRAINT integration_connections_org_provider_unique UNIQUE (organization_id, provider)
);
CREATE INDEX IF NOT EXISTS integration_connections_org_idx ON integration_connections (organization_id, provider);

CREATE TABLE IF NOT EXISTS integration_oauth_states (
  state_hash text PRIMARY KEY,
  provider text NOT NULL,
  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS integration_oauth_states_expiry_idx ON integration_oauth_states (expires_at);

CREATE TABLE IF NOT EXISTS integration_sync_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  provider text NOT NULL,
  external_id text NOT NULL,
  document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  external_url text,
  source_updated_at timestamptz,
  synced_at timestamptz NOT NULL DEFAULT NOW(),
  CONSTRAINT integration_sync_items_unique UNIQUE (organization_id, provider, external_id)
);
CREATE INDEX IF NOT EXISTS integration_sync_items_org_provider_idx ON integration_sync_items (organization_id, provider);
'@
$envBlock = @'

# Lumorius integrations (fill credentials only for providers you enable)
INTEGRATIONS_API_BASE_URL=http://localhost:3001/api/v1
INTEGRATION_ENCRYPTION_KEY=
LUMORIUS_PLATFORM_ORGANIZATION_ID=
GOOGLE_CLIENT_ID=
GOOGLE_CLIENT_SECRET=
MICROSOFT_CLIENT_ID=
MICROSOFT_CLIENT_SECRET=
SLACK_CLIENT_ID=
SLACK_CLIENT_SECRET=
NOTION_CLIENT_ID=
NOTION_CLIENT_SECRET=
GITHUB_CLIENT_ID=
GITHUB_CLIENT_SECRET=
ATLASSIAN_CLIENT_ID=
ATLASSIAN_CLIENT_SECRET=
ZOOM_CLIENT_ID=
ZOOM_CLIENT_SECRET=
HUBSPOT_CLIENT_ID=
HUBSPOT_CLIENT_SECRET=
SALESFORCE_CLIENT_ID=
SALESFORCE_CLIENT_SECRET=
LINEAR_CLIENT_ID=
LINEAR_CLIENT_SECRET=
DROPBOX_CLIENT_ID=
DROPBOX_CLIENT_SECRET=
INTERCOM_CLIENT_ID=
INTERCOM_CLIENT_SECRET=
PAGERDUTY_CLIENT_ID=
PAGERDUTY_CLIENT_SECRET=
DATADOG_SITE=datadoghq.com
SALESFORCE_LOGIN_URL=https://login.salesforce.com
SALESFORCE_API_VERSION=v61.0
'@

$servicePath = '.\apps\api\src\integrations\integrations.service.ts'
$controllerPath = '.\apps\api\src\integrations\integrations.controller.ts'
$modulePath = '.\apps\api\src\integrations\integrations.module.ts'
$pagePath = '.\apps\web\src\app\(dashboard)\integrations\page.tsx'
$appModulePath = '.\apps\api\src\app.module.ts'
$documentsModulePath = '.\apps\api\src\documents\documents.module.ts'

foreach ($path in @($servicePath, $controllerPath, $modulePath, $pagePath, $appModulePath, $documentsModulePath)) {
  if (-not (Test-Path -LiteralPath $path)) { throw "Required source file missing: $path. Nothing has been overwritten." }
}

# Prepare document-module export so the integration service reuses the existing ingestion/indexing pipeline.
$documentsModule = Read-Normalized $documentsModulePath
if ($documentsModule -notmatch "from './documents\.service'") {
  throw 'Could not find the DocumentsService import in documents.module.ts; inspect the module before patching.'
}
if ($documentsModule -notmatch '(?s)exports\s*:\s*\[[^\]]*\bDocumentsService\b') {
  if ($documentsModule -match '(?s)exports\s*:\s*\[') {
    $documentsModule = [regex]::Replace($documentsModule, '(?s)(exports\s*:\s*\[)', '$1DocumentsService, ', 1)
  } elseif ($documentsModule -match '(?m)^([ \t]*)providers\s*:') {
    $documentsModule = [regex]::Replace($documentsModule, '(?m)^([ \t]*)providers\s*:', '$1exports: [DocumentsService],' + "`n" + '$1providers:', 1)
  } else {
    throw 'Could not safely add DocumentsService to documents.module.ts exports.'
  }
}

# Register the module without duplicating it; ensure @OnEvent hooks have an EventEmitterModule.
$appModule = Read-Normalized $appModulePath
if ($appModule -notmatch "from './integrations/integrations\.module';") {
  $billingImport = "import { BillingModule } from './billing/billing.module';"
  if (-not $appModule.Contains($billingImport)) { throw 'Could not find BillingModule import in app.module.ts.' }
  $appModule = $appModule.Replace($billingImport, "$billingImport`nimport { IntegrationsModule } from './integrations/integrations.module';")
}
if ($appModule -notmatch '(?m)^\s+IntegrationsModule,\s*$') {
  if (-not $appModule.Contains('    BillingModule,')) { throw 'Could not find BillingModule in AppModule imports.' }
  $appModule = $appModule.Replace('    BillingModule,', "    BillingModule,`n    IntegrationsModule,")
}
if ($appModule -notmatch "from '@nestjs/event-emitter';") {
  $importAnchor = "import { IntegrationsModule } from './integrations/integrations.module';"
  $appModule = $appModule.Replace($importAnchor, "$importAnchor`nimport { EventEmitterModule } from '@nestjs/event-emitter';")
}
if ($appModule -notmatch 'EventEmitterModule\.forRoot\s*\(') {
  if (-not $appModule.Contains('    BillingModule,')) { throw 'Could not find a safe location for EventEmitterModule.forRoot().' }
  $appModule = $appModule.Replace('    BillingModule,', "    EventEmitterModule.forRoot(),`n    BillingModule,")
}

# Select a new migration number; preserve all prior migration files.
$schemaDir = '.\database\schema'
if (-not (Test-Path -LiteralPath $schemaDir)) { throw 'database/schema directory not found.' }
$maxVersion = 0
foreach ($file in (Get-ChildItem $schemaDir -File -Filter '*.sql')) {
  if ($file.Name -match '^(\d+)_') { if ([int]$Matches[1] -gt $maxVersion) { $maxVersion = [int]$Matches[1] } }
}
$migrationPath = Join-Path $schemaDir ('{0:D3}_integration_sync.sql' -f ($maxVersion + 1))
if (Test-Path -LiteralPath $migrationPath) { throw "Migration already exists: $migrationPath. Stop and inspect existing schema history." }

# Backup everything that will change before writing.
foreach ($path in @($servicePath, $controllerPath, $modulePath, $pagePath, $appModulePath, $documentsModulePath, '.\.env.example', '.\.env', '.\apps\api\.env')) { Backup-IfExists $path }
Write-Utf8 $servicePath $service
Write-Utf8 $controllerPath $controller
Write-Utf8 $modulePath $module
Write-Utf8 $pagePath $page
Write-Utf8 $documentsModulePath $documentsModule
Write-Utf8 $appModulePath $appModule
Write-Utf8 $migrationPath $migration

# Add documented placeholders without overwriting existing credentials or rotating the encryption key.
Append-MissingEnv '.\.env.example' $envBlock
$activeEnvTargets = @()
if (Test-Path '.\apps\api\.env') { $activeEnvTargets += '.\apps\api\.env' }
elseif (Test-Path '.\.env') { $activeEnvTargets += '.\.env' }
else {
  New-Item -ItemType File -Path '.\apps\api\.env' -Force | Out-Null
  $activeEnvTargets += '.\apps\api\.env'
}
foreach ($envPath in $activeEnvTargets) { Append-MissingEnv $envPath $envBlock }

# Generate an encryption key only if none exists; retain and replicate one existing stable value.
$keys = @()
foreach ($envPath in @('.\.env', '.\apps\api\.env')) {
  if (Test-Path $envPath) {
    $match = [regex]::Match((Read-Normalized $envPath), '(?m)^INTEGRATION_ENCRYPTION_KEY=([a-fA-F0-9]{64})\s*$')
    if ($match.Success) { $keys += $match.Groups[1].Value.ToLowerInvariant() }
  }
}
$uniqueKeys = @($keys | Select-Object -Unique)
if ($uniqueKeys.Count -gt 1) { throw 'Different valid integration encryption keys exist in root .env and apps/api/.env. Resolve before connecting providers.' }
if ($uniqueKeys.Count -eq 0) {
  $integrationKey = (& node -e "process.stdout.write(require('crypto').randomBytes(32).toString('hex'))").Trim()
  if ($LASTEXITCODE -ne 0 -or $integrationKey -notmatch '^[a-fA-F0-9]{64}$') { throw 'Could not generate integration encryption key.' }
} else { $integrationKey = $uniqueKeys[0] }
foreach ($envPath in @('.\.env', '.\apps\api\.env')) {
  if (Test-Path $envPath) {
    $envText = Read-Normalized $envPath
    if ($envText -match '(?m)^INTEGRATION_ENCRYPTION_KEY=') {
      $envText = [regex]::Replace($envText, '(?m)^INTEGRATION_ENCRYPTION_KEY=.*$', "INTEGRATION_ENCRYPTION_KEY=$integrationKey")
    } else { $envText += "`nINTEGRATION_ENCRYPTION_KEY=$integrationKey`n" }
    if ($envText -notmatch '(?m)^INTEGRATIONS_API_BASE_URL=') { $envText += "`nINTEGRATIONS_API_BASE_URL=http://localhost:3001/api/v1`n" }
    if ($envText -notmatch '(?m)^LUMORIUS_PLATFORM_ORGANIZATION_ID=') { $envText += "`nLUMORIUS_PLATFORM_ORGANIZATION_ID=`n" }
    Write-Utf8 $envPath $envText
  }
}
Write-Host 'Backups saved; encryption key value was not printed.' -ForegroundColor Green

# Apply additive migration to current local DB if Docker is available and the expected container is running.
$docker = Get-Command docker -ErrorAction SilentlyContinue
if ($docker) {
  $containers = (& docker ps --format '{{.Names}}' 2>$null) -join "`n"
  if ($LASTEXITCODE -eq 0 -and $containers -match '(?m)^lumorius_postgres$') {
    & docker cp (Resolve-Path $migrationPath).Path 'lumorius_postgres:/tmp/lumorius_integration_sync.sql'
    if ($LASTEXITCODE -ne 0) { throw 'Could not copy migration into lumorius_postgres.' }
    & docker exec lumorius_postgres psql -v ON_ERROR_STOP=1 -U lumorius -d lumorius_db -f /tmp/lumorius_integration_sync.sql
    if ($LASTEXITCODE -ne 0) { throw 'Database migration failed. Read the psql error; all edited files are backed up.' }
    Write-Host 'Database migration applied.' -ForegroundColor Green
  } else {
    Write-Warning "lumorius_postgres is not running. Migration is saved at $migrationPath; apply it before testing Sync now."
  }
}

Write-Host "`n===== CLEANING OLD API BUILD OUTPUT =====" -ForegroundColor Cyan
if (Test-Path '.\apps\api\dist') { Remove-Item -LiteralPath '.\apps\api\dist' -Recurse -Force }
Write-Host "`n===== API BUILD =====" -ForegroundColor Cyan
$apiOutput = & pnpm --filter @lumorius/api build 2>&1
$apiCode = $LASTEXITCODE
$apiOutput | Tee-Object -FilePath '.\api-integrations-v2-build.log'
if ($apiCode -ne 0) {
  Write-Host "API build failed. Log: .\api-integrations-v2-build.log" -ForegroundColor Red
  Write-Host "Backups: $backupDir" -ForegroundColor Yellow
  Read-Host 'Press Enter to return to PowerShell'
  return
}
Write-Host 'API build passed.' -ForegroundColor Green

Write-Host "`n===== WEB BUILD =====" -ForegroundColor Cyan
$webOutput = & pnpm --filter @lumorius/web build 2>&1
$webCode = $LASTEXITCODE
$webOutput | Tee-Object -FilePath '.\web-integrations-v2-build.log'
if ($webCode -ne 0) {
  Write-Host "Web build failed. Log: .\web-integrations-v2-build.log" -ForegroundColor Red
  Write-Host "Backups: $backupDir" -ForegroundColor Yellow
  Read-Host 'Press Enter to return to PowerShell'
  return
}
Write-Host 'Web build passed.' -ForegroundColor Green

Write-Host "`nConnector upgrade applied. Backups: $backupDir" -ForegroundColor Green
Write-Host "Migration: $migrationPath"
Write-Host 'OAuth callback URI pattern: http://localhost:3001/api/v1/integrations/PROVIDER_ID/callback'
Write-Host 'Supported IDs include google-drive, gmail, google-meet, onedrive, outlook-mail, slack, notion, github, jira, zoom, hubspot, salesforce, linear, dropbox, intercom, pagerduty, datadog, zapier and make.'
Write-Host 'OAuth providers require app credentials and redirect URIs configured with each provider. Zapier/Make accept HTTPS webhook URLs. Sync imports bounded recent records, queues them into the existing document indexer, and currently skips previously imported source IDs.'
Read-Host 'Press Enter to finish'
